export const familyPalette={R:'#f4770b',C:'#009ee8',L:'#a83ee8'};
export function familyOf(ref){return /^R\d/.test(ref)?'R':/^C\d/.test(ref)?'C':/^L\d/.test(ref)?'L':null;}
export const familyLegend='<span class="familyKey"><i style="background:#f4770b"></i>R · Resistencias</span><span class="familyKey"><i style="background:#009ee8"></i>C · Condensadores / capacitores</span><span class="familyKey"><i style="background:#a83ee8"></i>L · Bobinas / inductores</span>';
export function tintComponentFamilies(root,enabled,THREE){if(!root)return;root.traverse(o=>{if(o.userData.preserveMarking)return;if(o.userData.componentEntries){if(o.material?.metalness>.5)return;if(!enabled&&!o.userData.familyWasEnabled)return;for(let i=0;i<o.count;i++){const f=familyOf(o.userData.componentEntries[i].name);if(f)o.setColorAt(i,new THREE.Color(enabled?familyPalette[f]:o.userData.baseColor));}o.userData.familyWasEnabled=enabled;if(o.instanceColor)o.instanceColor.needsUpdate=true;return;}if(!o.isMesh||o.material?.metalness>.5)return;const f=familyOf(o.userData.component?.name||'');if(!f||!o.material?.color||o.material.map)return;if(!o.userData.familyOriginal){o.userData.familyOriginal=o.material.color.clone();o.material=o.material.clone();}o.material.color.copy(enabled?new THREE.Color(familyPalette[f]):o.userData.familyOriginal);if(enabled&&o.material.emissive){o.material.emissive.set('#000000');o.material.emissiveIntensity=0;}});}
